INSERT INTO questions (id, module_id, sub_module_id, text, option_a, option_b, option_c, option_d, correct_answer, explanation, reference, difficulty) VALUES
('fra-041', 'francais', 'fra-1', 'Lisez cet extrait d''un contrat de partenariat : « Le présent contrat est renouvelable par tacite reconduction, sauf dénonciation par l''une des parties adressée par lettre recommandée au moins trois mois avant l''échéance. » Que doit faire le conducteur qui souhaite arrêter le partenariat ?', 'Envoyer une lettre recommandée au plus tard 3 mois avant l''échéance', 'Attendre l''échéance : le contrat s''arrêtera automatiquement', 'Prévenir son partenaire par téléphone la veille de l''échéance', 'Cesser simplement toute activité avec le partenaire', 'A', 'La tacite reconduction reconduit le contrat automatiquement, sauf si l''on respecte à la fois la FORME (lettre recommandée) et le DÉLAI (3 mois avant l''échéance). Sans démarche, le contrat repart pour une période complète.', 'Module 5 – Français : compréhension de texte', 'moyen'::question_difficulty),
('fra-042', 'francais', 'fra-1', 'Lisez cet avis affiché en gare : « En raison de travaux, la dépose-minute du parvis est fermée jusqu''au 15 mars inclus. Les véhicules de transport de personnes sont invités à utiliser l''accès situé rue de Metz. » Que comprend le conducteur ?', 'Il doit déposer ses clients rue de Metz jusqu''au 15 mars compris', 'Il peut utiliser le parvis à partir du 15 mars au matin', 'La gare est totalement fermée aux taxis et VTC', 'L''avis ne concerne que les véhicules particuliers', 'A', '« Jusqu''au 15 mars inclus » signifie que la fermeture couvre le 15 mars : l''accès de remplacement rue de Metz s''applique ce jour-là aussi. L''avis vise explicitement les véhicules de transport de personnes.', 'Module 5 – Français : compréhension de texte', 'moyen'::question_difficulty),
('fra-043', 'francais', 'fra-1', 'Lisez cette clause d''assurance : « La garantie ne s''applique pas lorsque le véhicule est conduit par une personne ne figurant pas aux conditions particulières. » Un conducteur prête son véhicule à un confrère non déclaré, qui a un accident. Que se passe-t-il ?', 'L''assureur peut refuser sa garantie : le conducteur n''était pas déclaré', 'L''assurance couvre normalement, l''important est que le véhicule soit assuré', 'La garantie s''applique à moitié', 'L''assureur couvre à condition de déclarer le confrère après l''accident', 'A', 'La clause exclut la garantie si le conducteur ne figure pas aux conditions particulières. L''assurance couvre un véhicule ET des conducteurs nommément désignés : prêter le volant à une personne non déclarée fait tomber la couverture.', 'Module 5 – Français : compréhension de texte', 'moyen'::question_difficulty),
('fra-044', 'francais', 'fra-2', 'Quelle phrase est correctement orthographiée pour un message professionnel à un client ?', 'Je vous confirme que je serai devant votre hôtel à 8 h.', 'Je vous confirme que je serais devant votre hôtel à 8 h.', 'Je vous confirme que je serait devant votre hôtel à 8 h.', 'Je vous confirme que je serais devant votre hotêl à 8 h.', 'A', 'Il s''agit d''un engagement ferme au futur : « je serai ». « Je serais » est un conditionnel (hypothèse), « je serait » n''existe pas.', 'Module 5 – Français : expression écrite', 'moyen'::question_difficulty),
('fra-045', 'francais', 'fra-2', 'Un client professionnel vous demande de rectifier une facture. Quelle formulation est la plus adaptée ?', 'Je vous prie de bien vouloir trouver ci-joint la facture rectifiée.', 'Voilà la facture corrigée, j''espère que c''est bon cette fois.', 'Ci-joint la facture, il fallait me le dire avant.', 'Je vous envoie la facture rectifié comme demandé.', 'A', 'La formule « Je vous prie de bien vouloir trouver ci-joint » est la tournure professionnelle attendue. Les autres propositions sont trop familières, désinvoltes, ou comportent une faute d''accord (« rectifié » au lieu de « rectifiée »).', 'Module 5 – Français : expression écrite', 'facile'::question_difficulty),
('fra-046', 'francais', 'fra-2', 'Quelle phrase ne contient AUCUNE faute ?', 'Les courses que j''ai effectuées ce mois-ci ont toutes été réglées.', 'Les courses que j''ai effectué ce mois-ci ont toutes été réglées.', 'Les courses que j''ai effectuées ce mois-ci ont toutes étés réglées.', 'Les course que j''ai effectuées ce mois-ci ont toutes été réglées.', 'A', 'Avec l''auxiliaire AVOIR, le participe s''accorde avec le complément d''objet direct placé avant : « que » reprend « les courses » → « effectuées ». Avec ÊTRE, « été » est invariable.', 'Module 5 – Français : expression écrite', 'difficile'::question_difficulty),
('fra-047', 'francais', 'fra-1', 'Lisez ce message reçu d''un client : « Je vous confirme la course de demain, mais je risque d''avoir dix minutes de retard. Merci de m''attendre le cas échéant. » Que signifie « le cas échéant » ?', 'Si cela se produit', 'Dans tous les cas, obligatoirement', 'En cas d''urgence uniquement', 'À la place de ce qui était prévu', 'A', '« Le cas échéant » signifie « si le cas se présente », « si cela arrive ». Le client demande d''être attendu seulement s''il est effectivement en retard.', 'Module 5 – Français : compréhension de texte', 'moyen'::question_difficulty),
('fra-048', 'francais', 'fra-2', 'Vous devez informer un client que son forfait aéroport ne s''applique plus car il a demandé un détour. Quelle formulation choisir ?', 'Le détour que vous souhaitez sort du forfait : le prix sera calculé au compteur, je vous préviens avant de m''engager.', 'Ce n''est plus le forfait, tant pis pour vous, ça va coûter plus cher.', 'Je vous préviendrai du prix à l''arrivée, on verra bien.', 'Le forfait s''applique quand même, ne vous inquiétez pas.', 'A', 'L''information doit être donnée AVANT le détour, clairement et sans jugement. Annoncer le prix seulement à l''arrivée expose à un litige ; prétendre que le forfait s''applique encore serait faux.', 'Module 5 – Français : expression écrite', 'moyen'::question_difficulty),
('fra-049', 'francais', 'fra-1', 'Lisez cette note de service : « Les conducteurs veilleront à ce que le véhicule soit nettoyé avant chaque prise de service, faute de quoi l''accès à la station pourra leur être refusé. » Que risque un conducteur au véhicule sale ?', 'Se voir refuser l''accès à la station', 'Une amende automatique de la préfecture', 'Rien : c''est une simple recommandation', 'Le retrait immédiat de sa carte professionnelle', 'A', '« Faute de quoi » introduit la conséquence en cas de non-respect : ici, le refus d''accès à la station. Le texte ne prévoit ni amende ni retrait de carte.', 'Module 5 – Français : compréhension de texte', 'moyen'::question_difficulty),
('fra-050', 'francais', 'fra-2', 'Parmi ces phrases destinées à un client, laquelle est correcte ?', 'Pourriez-vous me préciser l''adresse exacte, s''il vous plaît ?', 'Pourriez-vous me précisez l''adresse exacte, s''il vous plaît ?', 'Pouvez-vous me précisé l''adresse exacte, s''il vous plait ?', 'Pourriez vous me préciser l''adresse exact, s''il vous plaît ?', 'A', 'Après « pourriez-vous », le verbe se met à l''infinitif : « préciser ». Le trait d''union est obligatoire dans l''inversion « pourriez-vous », et « exacte » s''accorde avec « adresse » (féminin).', 'Module 5 – Français : expression écrite', 'moyen'::question_difficulty),
('fra-051', 'francais', 'fra-1', 'Un client écrit : « Je souhaite réserver un véhicule pour quatre personnes, sachant que nous aurons deux valises chacun. » Quelles informations le conducteur doit-il retenir pour préparer la course ?', 'Quatre passagers à transporter', 'Huit valises à charger', 'Deux passagers avec quatre valises', 'Un véhicule de neuf places est obligatoire', 'A,B', 'Le message donne deux informations concrètes : quatre personnes, et deux valises par personne, soit huit valises au total. Rien n''impose un véhicule de neuf places, mais le volume de bagages conditionne le choix du véhicule.', 'Module 5 – Français : compréhension de texte', 'moyen'::question_difficulty),
('fra-052', 'francais', 'fra-2', 'Comment rédiger correctement l''objet d''un courriel confirmant une course ?', 'Confirmation course du 12 juin – 14 h – Aéroport CDG', 'confirmation', 'URGENT !!! COURSE CONFIRMÉE !!!', 'Bonjour, je vous écris pour vous confirmer votre course de demain', 'A', 'Un bon objet est court, précis et informatif : nature du message, date, heure, destination. Un objet vide de sens, en majuscules ou constitué d''une phrase entière est inefficace.', 'Module 5 – Français : expression écrite', 'facile'::question_difficulty),
('fra-053', 'francais', 'fra-1', 'Lisez cet extrait de conditions générales : « Toute annulation intervenant moins de deux heures avant l''heure de prise en charge donnera lieu à facturation de 50 % du montant de la course. » Un client annule trois heures avant. Que doit facturer le conducteur ?', 'Rien : l''annulation est intervenue plus de deux heures avant', '50 % du montant de la course', '100 % du montant de la course', 'Un forfait libre, fixé par le conducteur', 'A', 'La pénalité ne s''applique qu''aux annulations survenant à MOINS de deux heures de la prise en charge. À trois heures, le client est dans les temps : aucune facturation n''est prévue par la clause.', 'Module 5 – Français : compréhension de texte', 'moyen'::question_difficulty),
('fra-054', 'francais', 'fra-2', 'Quelle phrase est correcte dans un compte rendu écrit à votre école ?', 'Le client m''a demandé de l''emmener à la gare ; je l''y ai conduit sans difficulté.', 'Le client m''a demandé de l''amener à la gare ; je l''ai conduit la-bas sans difficultés.', 'Le client ma demandé de l''emmener à la gare, je l''ai conduit sans difficulté.', 'Le client m''a demander de l''emmener à la gare ; je l''y ai conduit sans difficulté.', 'A', '« M''a » (verbe avoir) et non « ma » (possessif) ; « demandé » (participe) et non « demander » ; « emmener » s''emploie pour une personne que l''on conduit d''un lieu à un autre.', 'Module 5 – Français : expression écrite', 'difficile'::question_difficulty),
('fra-055', 'francais', 'fra-1', 'Lisez cette consigne reçue d''une conciergerie : « Merci de patienter au point de rendez-vous ; le client vous rejoindra dès la fin de sa réunion, sans excéder trente minutes d''attente. » Que comprend le conducteur ?', 'Il attend le client, avec une attente plafonnée à trente minutes', 'Il doit partir immédiatement si le client n''est pas là', 'Il doit attendre le temps qu''il faudra, sans limite', 'Le client le rejoindra obligatoirement dans les cinq minutes', 'A', '« Sans excéder trente minutes » fixe un plafond : le conducteur patiente, mais l''attente ne dépassera pas trente minutes. Ce n''est ni une attente illimitée, ni une autorisation de partir tout de suite.', 'Module 5 – Français : compréhension de texte', 'moyen'::question_difficulty),
('ang-081', 'anglais', 'ang-2', 'A passenger says: “Could you drop me off at the corner, please? I''ll walk from there.” What does the driver do?', 'He stops safely at the corner and lets the passenger out on the pavement side', 'He drives to the exact address anyway, ignoring the request', 'He stops immediately in the middle of the road', 'He asks the passenger to pay extra for the change', 'A', '“Drop me off” means to let someone out of the vehicle. The driver complies, stopping safely on the pavement side — no extra charge applies for a shorter stop.', 'Module 6 – Anglais : conversation client', 'moyen'::question_difficulty),
('ang-082', 'anglais', 'ang-2', 'A client asks: “How long will it take to get to Orly?” Traffic is heavy. What is the best answer?', 'It should take about forty minutes, depending on traffic.', 'Exactly thirty-two minutes.', 'I don''t know, we will see.', 'It is impossible to say anything.', 'A', 'A professional gives a realistic estimate with a safety word (“about”, “depending on traffic”). An exact time is a promise that heavy traffic may break; refusing to answer is unhelpful.', 'Module 6 – Anglais : conversation client', 'moyen'::question_difficulty),
('ang-083', 'anglais', 'ang-1', 'At the airport, a passenger says: “My flight was delayed and my luggage is still missing.” What has happened?', 'His flight arrived late', 'His bags have not been found yet', 'He has missed his flight completely', 'He has too many suitcases', 'A,B', '“Delayed” means late, and “missing luggage” means the bags have not arrived. Nothing indicates a missed flight or excess baggage.', 'Module 6 – Anglais : vocabulaire professionnel', 'moyen'::question_difficulty),
('ang-084', 'anglais', 'ang-4', 'The client is cold. Which sentence is the most professional?', 'Would you like me to turn the heating up?', 'You are cold? Not my problem.', 'Turn it yourself, the button is there.', 'It is not cold in here.', 'A', 'The offer is polite, uses a modal (“would you like”), and leaves the choice to the client. The other answers are dismissive or contradict the passenger.', 'Module 6 – Anglais : phrases types', 'facile'::question_difficulty),
('ang-085', 'anglais', 'ang-2', 'A tourist asks: “Is it far from here to the Louvre?” You are at Gare de Lyon. What do you answer?', 'It''s about fifteen minutes by car, on the right bank of the Seine.', 'Yes, very far, maybe two hours.', 'I cannot tell you, ask someone else.', 'It is just next door, you can walk in five minutes.', 'A', 'From Gare de Lyon, the Louvre is roughly fifteen minutes by car along the right bank. The other answers are wrong or unhelpful.', 'Module 6 – Anglais : conversation client', 'moyen'::question_difficulty),
('ang-086', 'anglais', 'ang-4', 'You need to tell a passenger to fasten his seat belt. Which sentence do you use?', 'Could you fasten your seat belt, please?', 'Put your belt now.', 'You must obey the law immediately.', 'The belt is compulsory, do it or get out.', 'A', 'A polite request with “could you … please” obtains compliance without confrontation. The other formulations are aggressive and damage the service relationship.', 'Module 6 – Anglais : phrases types', 'facile'::question_difficulty),
('ang-087', 'anglais', 'ang-1', 'A client says: “I need a receipt for my company.” What must the driver provide?', 'A written proof of payment for the ride', 'A business card', 'A copy of his professional card', 'A price list of all his fares', 'A', 'A “receipt” is the written proof of payment (the note/facture in French), which the client needs for his expense report.', 'Module 6 – Anglais : vocabulaire professionnel', 'facile'::question_difficulty),
('ang-088', 'anglais', 'ang-2', 'During the ride, the passenger takes an important phone call. What should the driver do?', 'Lower the radio and avoid speaking until the call is over', 'Continue the conversation as before', 'Turn the radio up to cover the conversation', 'Ask the passenger to end the call', 'A', 'Discretion is expected: the driver lowers any music and stays silent so the passenger can talk. Interrupting or listening in is unprofessional.', 'Module 6 – Anglais : conversation client', 'facile'::question_difficulty),
('ang-089', 'anglais', 'ang-3', 'A tourist asks: “Which day is the Louvre closed?” What is the correct answer?', 'On Tuesdays.', 'On Sundays.', 'It never closes.', 'Every morning before noon.', 'A', 'The Louvre Museum is closed on Tuesdays — a very common question from tourists, and useful knowledge for a Paris driver.', 'Module 6 – Anglais : tourisme international', 'moyen'::question_difficulty),
('ang-090', 'anglais', 'ang-4', 'The road you planned is blocked by a demonstration. How do you inform your passenger?', 'There is a demonstration ahead, so I will take another route. It may take a few extra minutes.', 'We are stuck, there is nothing I can do.', 'It is not my fault, the police blocked everything.', 'We will wait here until it is finished.', 'A', 'The professional answer states the cause, the solution and the consequence. Complaining or waiting passively leaves the client without information or options.', 'Module 6 – Anglais : phrases types', 'moyen'::question_difficulty),
('ang-091', 'anglais', 'ang-1', 'What does the driver mean by: “I''ll pick you up at the arrivals hall, gate 4”?', 'He will collect the passenger at the arrivals area', 'He will wait at gate 4', 'He will leave the passenger at the departures area', 'He will call the passenger from home', 'A,B', '“Pick you up” means to collect the passenger, and “gate 4” gives the precise meeting point in the arrivals hall. It is not a drop-off at departures.', 'Module 6 – Anglais : vocabulaire professionnel', 'moyen'::question_difficulty),
('ang-092', 'anglais', 'ang-2', 'A passenger with a wheelchair asks whether you can take him. What is the appropriate answer?', 'Of course. May I help you with the wheelchair?', 'Sorry, I do not take wheelchairs.', 'Only if you can fold it yourself.', 'It will be more expensive.', 'A', 'Refusing a passenger because of a disability is unlawful, and charging extra for it is discriminatory. The correct response accepts the ride and offers help without imposing it.', 'Module 6 – Anglais : conversation client', 'moyen'::question_difficulty),
('ang-093', 'anglais', 'ang-3', 'A tourist asks: “What is the best way to see Paris from above?” Which answer is the most useful?', 'The Eiffel Tower, Montparnasse Tower or the Arc de Triomphe all have viewpoints.', 'There is no way to see Paris from above.', 'Only from an aeroplane.', 'From the Seine river boats.', 'A', 'Several viewpoints exist: the Eiffel Tower, the Montparnasse Tower (famous because the view includes the Eiffel Tower) and the terrace of the Arc de Triomphe. River boats offer a view from the water, not from above.', 'Module 6 – Anglais : tourisme international', 'moyen'::question_difficulty),
('ang-094', 'anglais', 'ang-4', 'You have arrived at the destination. Which closing sentence is the most professional?', 'Here we are. Please make sure you have all your belongings. Have a pleasant stay!', 'That''s it, goodbye.', 'Get out please, I have another client.', 'Finally, we arrived.', 'A', 'The closing combines arrival announcement, a reminder about personal belongings, and a courteous farewell — the three elements expected at the end of a ride.', 'Module 6 – Anglais : phrases types', 'facile'::question_difficulty)
